pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to ensure we treat arbitrary callers; the rule must hold for ALL callers
    function testFuzz_property(address caller) public {
        // keep caller in the wide admissible domain (allow zero address too)
        // perform the call to the external pure function version()
        bool ok;
        string memory v;
        // call from arbitrary caller
        vm.prank(caller);
        try c.version() returns (string memory ret) {
            ok = true;
            v = ret;
        } catch {
            ok = false;
            v = "";
        }

        // The reference contract always returns "1.0.0" (and does not revert),
        // so for every admissible caller the call succeeds and returns that exact string.
        // We assert that the call succeeded and returned "1.0.0".
        assertTrue(ok && (keccak256(abi.encodePacked(v)) == keccak256(abi.encodePacked("1.0.0"))));
    }
}

