pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz a bytes calldata blob that will be used to call the contract via low-level call.
    // This lets the fuzzer explore different encodings (including the exact selector for version())
    // The universal property: calling version() (or any calldata that invokes it) returns a non-empty string in the reference.
    function testFuzz_property(bytes memory input) public {
        // perform a low-level staticcall to the contract with fuzzed calldata
        (bool ok, bytes memory ret) = address(c).call(input);

        // If the call succeeded and returned data, require that the returned bytes (ABI-encoded string)
        // decode to a string with non-zero length. For calls that do not succeed or do not return a string,
        // we treat them as not violating the property because the reference contract's behavior for version()
        // is that when it returns a string it is non-empty. The mutant returns an empty string for the same
        // call that targets version(), which will make this assertion fail for some input (specifically the
        // calldata matching the version() selector).

        // We only assert when the call succeeded and returned at least 32 bytes (string ABI has offset + length),
        // which indicates a valid ABI-encoded dynamic string was returned.
        bool holds = true;
        if (ok && ret.length >= 32) {
            // decode the returned data as string in a safe manner
            // ABI encoding for string: offset (32) then length (32) then data
            // If ret is exactly the abi.encode(string), we can decode via abi.decode
            // Use try/catch to avoid decode revert if data is malformed
            // But solidity's abi.decode reverts on malformed length; wrap in low-level check
            // We'll attempt decode in a try/catch by using an internal helper function
            string memory s = _tryDecodeString(ret);
            // property: the returned string must be non-empty
            if (bytes(s).length == 0) {
                holds = false;
            }
        }

        assertTrue(holds);
    }

    // helper to decode string without reverting the test contract on bad ABI: returns empty string on decode failure
    function _tryDecodeString(bytes memory data) internal pure returns (string memory) {
        // minimal safe decoding: require at least 64 bytes for offset + length
        if (data.length < 64) {
            return "";
        }
        // try abi.decode in a low-level assembly block to catch failures and return empty
        // Using solidity try/catch on internal pure functions isn't available for abi.decode, so we do a guarded decode
        // Check the offset value equals 0x20 (32)
        uint256 offset;
        assembly {
            offset := mload(add(data, 32))
        }
        if (offset != 32) {
            return "";
        }
        // read length
        uint256 len;
        assembly {
            len := mload(add(data, 64))
        }
        // ensure declared length fits in returned data
        if (data.length < 64 + ((len + 31) / 32) * 32) {
            return "";
        }
        // safe to decode
        string memory s = abi.decode(data, (string));
        return s;
    }
}

