pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the raw calldata bytes that will be sent to the contract.
    // General rule: for any calldata bytes, a low-level call to c with the version() selector
    // should succeed and return a non-empty string on the reference implementation.
    // The mutant returns an empty string for some calldata, which this test will catch.
    function testFuzz_property(bytes memory calldataBytes) public {
        // Keep domain wide: disallow only absurdly large inputs that make the test slow
        // but allow all realistic calldata; bound to, say, 0..1024 bytes.
        uint256 len = bound(calldataBytes.length, 0, 1024);
        assembly { mstore(calldataBytes, len) }

        // Prepare calldata: 4-byte selector of version() followed by arbitrary extra bytes.
        // version() selector = bytes4(keccak256("version()"))
        bytes memory sel = abi.encodeWithSelector(bytes4(keccak256("version()")));
        bytes memory callData = new bytes(sel.length + calldataBytes.length);
        for (uint i = 0; i < sel.length; i++) {
            callData[i] = sel[i];
        }
        for (uint i = 0; i < calldataBytes.length; i++) {
            callData[sel.length + i] = calldataBytes[i];
        }

        // Perform low-level call to c with the crafted calldata.
        (bool ok, bytes memory ret) = address(c).call(callData);

        // The reference contract always returns a non-empty string (bytes length > 0) for any calldata that successfully calls the external selector.
        // So we assert: if the call succeeded, the returned data length must be > 0.
        // This single assertion holds for the reference and is violated by the mutant which can return empty string (zero-length return data) for some inputs.
        if (ok) {
            assertTrue(ret.length > 0);
        } else {
            // If the call reverted, assert false to indicate the reference should not revert on any calldata
            // but keep a single assertTrue as required: assertTrue(false) in this branch.
            assertTrue(false);
        }
    }
}

