pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz a bytes calldata blob which will be forwarded in a low-level staticcall to c.version().
    // The reference's external pure function version() ignores calldata and always returns "1.0.0".
    // The mutant returns "x". We assert that the first byte of the returned string is '1'.
    function testFuzz_property(bytes calldata fuzzCalldata) public {
        // Keep domain wide; no assumptions so fuzzer can explore all calldata bytes.

        // Perform a low-level staticcall to cover the external entrypoint in arbitrary calldata shapes.
        (bool ok, bytes memory ret) = address(c).staticcall(fuzzCalldata);

        // If the call reverted, treat that as not satisfying the property (but reference should not revert on any calldata).
        // We convert success flag and return data into an observed boolean: ok && first byte == '1'
        bool observed = false;
        if (ok) {
            // For a valid returned string, ABI-encoded as (string), the return data is ABI encoding:
            // offset (32) | string length (32) | string bytes (ceil32)
            // We defensively check length before reading.
            if (ret.length >= 64) {
                // string length is at ret[32:64]
                uint256 strLen;
                assembly { strLen := mload(add(ret, 64)) }
                if (strLen >= 1 && ret.length >= 64 + ((strLen + 31) / 32) * 32) {
                    // first string byte located at ret[64]
                    bytes1 first;
                    assembly { first := mload(add(ret, 65)) }
                    observed = (first == 0x31); // ASCII '1' == 0x31
                }
            }
        }

        // The reference always returns "1.0.0" so observed must be true for ALL inputs.
        // The mutant that returns "x" will cause observed to be false for many inputs and thus fail this assertion.
        assertTrue(observed);
    }
}

