pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the calldata bytes that a caller might send when calling version()
    // The reference always returns "1.0.0" whose first byte is '1' (0x31).
    // The mutant may return another string like "x" whose first byte differs.
    function testFuzz_property(bytes memory data) public {
        // Keep domain wide but ensure data is not absurdly large to avoid OOG
        // Allow up to 1024 bytes
        vm.assume(data.length <= 1024);

        // We will call the external function `version()` on c using low-level call
        // with arbitrary calldata provided by the fuzzer. If the call succeeds
        // we decode the returned string and assert its first byte is '1'. If the
        // call reverts we treat that as out-of-domain and assume(false) so the
        // property is only required for completing calls.

        // Compose calldata: if data encodes exactly the selector+args for version(),
        // the call will invoke version; otherwise it may hit fallback and revert.
        // We instead always call the official selector for version() optionally
        // followed by the fuzzed tail bytes to allow fuzz to produce different
        // returndata shapes while keeping the entrypoint the same.
        bytes4 sel = bytes4(keccak256("version()"));
        bytes memory callData = abi.encodePacked(sel, data);

        (bool success, bytes memory ret) = address(c).call(callData);

        // Only consider successful calls as admissible inputs for the universal rule.
        if (!success) {
            // exclude reverts from admissible domain
            vm.assume(success);
        }

        // Decode returned string if possible. If decoding fails, treat as out-of-domain.
        // A well-behaved version() returns (string), so decoding should succeed for the
        // reference. If decoding would revert/invalid, exclude.
        // Try to decode: if ret is empty or malformed, assume(false).
        // Minimal check: ret length must be >= 32 (offset) + 32 (len)
        if (ret.length < 64) {
            vm.assume(ret.length >= 64);
        }

        // Decode string
        string memory s = abi.decode(ret, (string));
        bytes memory sb = bytes(s);

        // Require at least one byte in returned string for the property to make sense
        vm.assume(sb.length > 0);

        // The universal property: first byte must be ASCII '1' (0x31).
        // Reference returns "1.0.0" so this holds for all admissible inputs.
        // The mutant returning "x" will cause this assert to fail for some fuzz inputs.
        assertTrue(sb[0] == bytes1(uint8(0x31)));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to set L1 block values from an arbitrary caller and assert they did not change.
    // Parameters are the candidate new values; the caller of this test will be a non-depositor.
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Record prior values observed via public getters
        uint64 beforeNumber = c.number();
        uint64 beforeTimestamp = c.timestamp();
        uint256 beforeBasefee = c.basefee();
        bytes32 beforeHash = c.hash();
        uint64 beforeSequence = c.sequenceNumber();
        bytes32 beforeBatcher = c.batcherHash();
        uint256 beforeOverhead = c.l1FeeOverhead();
        uint256 beforeScalar = c.l1FeeScalar();

        // This call should revert or be prevented by the onlyDepositor modifier in the original contract.
        // In the mutant, the restriction is removed and the call will succeed and change state.
        // We make the call (state-changing) as its own top-level statement as required.
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        // After the call, on the original contract (P) the values must remain equal to before (unauthorized caller can't change them).
        // On the mutant (M) the values may differ, violating this assertion.
        assert(
            c.number() == beforeNumber &&
            c.timestamp() == beforeTimestamp &&
            c.basefee() == beforeBasefee &&
            c.hash() == beforeHash &&
            c.sequenceNumber() == beforeSequence &&
            c.batcherHash() == beforeBatcher &&
            c.l1FeeOverhead() == beforeOverhead &&
            c.l1FeeScalar() == beforeScalar
        );
    }
}

